#!/usr/bin/env bash
# Thin wrapper around scripts/deploy.py -- generated by Datrix, do not edit manually.
#
# This script does no deployment work of its own. It exists so an operator can
# run the deployment from a POSIX shell without thinking about interpreters:
# it anchors the working directory at the project root, makes sure the project
# virtual environment exists, activates it, hands every argument straight to
# scripts/deploy.py, and deactivates afterward. All deployment logic --
# every provider call, every retry, every check -- lives in that one Python
# script, so the bash and PowerShell entrypoints cannot drift apart.
set -euo pipefail

# The deployment script and this wrapper are siblings; every path the Python
# script uses is relative to the project root, so anchor there first. This
# makes 'scripts/deploy.sh' (from the project root) and './deploy.sh' (from
# inside the scripts folder) behave identically.
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"
cd "$PROJECT_ROOT"

VENV_DIR="$PROJECT_ROOT/.venv"

# Interpreter used ONLY to create the virtual environment on first run. Once
# the venv exists, its own interpreter runs the deployment.
find_bootstrap_python() {
  local candidate
  for candidate in python3 python; do
    if command -v "$candidate" >/dev/null 2>&1; then
      # Reject a Windows App Execution Alias stub (a zero-byte shim that opens
      # the Microsoft Store instead of running Python) -- it "exists" on PATH
      # but cannot create a venv, and its failure message names the Store
      # rather than the real problem.
      if "$candidate" -c "import sys; sys.exit(0)" >/dev/null 2>&1; then
        printf '%s\n' "$candidate"
        return 0
      fi
    fi
  done
  return 1
}

if [ ! -f "$VENV_DIR/bin/activate" ] && [ ! -f "$VENV_DIR/Scripts/activate" ]; then
  BOOTSTRAP_PYTHON="$(find_bootstrap_python || true)"
  if [ -z "$BOOTSTRAP_PYTHON" ]; then
    echo "ERROR: no usable Python interpreter found on PATH ('python3' or 'python')." >&2
    echo "  Expected: Python 3.11 or newer, used to create the project virtual environment at .venv/." >&2
    echo "  Fix: install Python 3.11+ and make sure 'python3' (or 'python') resolves, then re-run this script." >&2
    exit 1
  fi
  echo "==> Creating the project virtual environment (.venv/)"
  if ! "$BOOTSTRAP_PYTHON" -m venv "$VENV_DIR"; then
    echo "ERROR: could not create the project virtual environment at '$VENV_DIR'." >&2
    echo "  Command: $BOOTSTRAP_PYTHON -m venv $VENV_DIR" >&2
    echo "  Fix: ensure the interpreter ships the 'venv' module (on Debian/Ubuntu: apt install python3-venv) and that '$PROJECT_ROOT' is writable, then re-run." >&2
    exit 1
  fi
fi

# A venv created on Windows lays its scripts out under Scripts/, one created on
# a POSIX host under bin/. Both are reachable from this shell (Git Bash reads
# the Windows layout), so pick whichever this project actually has.
if [ -f "$VENV_DIR/bin/activate" ]; then
  # shellcheck disable=SC1091
  . "$VENV_DIR/bin/activate"
else
  # shellcheck disable=SC1091
  . "$VENV_DIR/Scripts/activate"
fi

# 'set -e' would abort before the deactivate below on any nonzero exit, so the
# status is captured explicitly and re-raised after the venv is deactivated.
status=0
python "$SCRIPT_DIR/deploy.py" "$@" || status=$?
deactivate
exit "$status"
